// План specs/job-create-sms.md 1.2 (кейс .qa/tests/job-create-sms/JS-02). Admin, компания «test», десктоп, EN.
// @writes: создаёт работу «QA-AUTO sms-text #8feef0 …» с техником QA-F5 tech и в конце переводит её в Cancelled.
// Проверяется ТЕЛО запроса POST functions/v1/send-sms (перехват до ответа, ответ — фейковый 422; реальный SMS не уходит).
import { test, expect } from '../../fixtures';
import {
  QA_CLIENT, cancelJob, createJobWithQaTech, expectOnlyQaTech, fakeSmsRejected, restoreTest, smsText, startInTest,
} from './job-sms-helpers';

test.describe('Job creation SMS: text (#8feef0)', () => {
  test('Assignment SMS body has "Job: JOB-XXXX" without the extra "Job" word #8feef0 @desktop @writes', async ({ asUser }) => {
    test.setTimeout(180_000);
    const page = await asUser('admin');
    await startInTest(page);
    const smsCalls = await fakeSmsRejected(page);
    let jobUrl = '';
    try {
      const created = await createJobWithQaTech(page, `QA-AUTO sms-text #8feef0 ${Date.now().toString(36)}`);
      jobUrl = created.jobUrl;

      await expect.poll(() => smsCalls.length, { message: 'запрос send-sms (перехвачен)', timeout: 20_000 }).toBeGreaterThan(0);
      const text = smsText(smsCalls[0]);
      const jobLine = text.split('\n').map((l) => l.trim()).find((l) => l.startsWith('Job:'));

      // Источник: «מה רצוי» — "Job: JOB-0088" בלבד, או מספר העבודה ואחריו תיאור/שם העבודה האמיתי אם קיים.
      // Комментарий программиста: имя «Job» / «Work order» / равное имени клиента не пишется.
      const m = jobLine?.match(/^Job: (JOB-\d{4})(?: (.+))?$/);
      expect(m, `строка «Job: JOB-XXXX» — получено «${jobLine}»`).toBeTruthy();
      expect(m![1], 'номер в SMS = номер созданной работы').toBe(created.jobCode);
      const suffix = m![2]?.trim();
      if (suffix !== undefined) {
        expect(['Job', 'Work order', QA_CLIENT], `после номера нет имени по умолчанию — «${jobLine}»`).not.toContain(suffix);
        expect(suffix, 'хвост — описание работы, если приложение берёт его как название').toContain('QA-AUTO sms-text #8feef0');
      }
    } finally {
      await cancelJob(page, jobUrl);
      await restoreTest(page);
    }
    expectOnlyQaTech(smsCalls);
  });
});
